package com.wms.entity;
import jakarta.persistence.*;
@Entity @Table(name="wms_workflow_node") public class WorkflowNode{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="definition_id",nullable=false)private WorkflowDefinition definition;@Column(nullable=false)private Integer sequence;@Column(nullable=false,length=64)private String name;@Column(nullable=false,length=16)private String approverType;@Column(nullable=false,length=64)private String approverValue;public Long getId(){return id;}public WorkflowDefinition getDefinition(){return definition;}public void setDefinition(WorkflowDefinition v){definition=v;}public Integer getSequence(){return sequence;}public void setSequence(Integer v){sequence=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getApproverType(){return approverType;}public void setApproverType(String v){approverType=v;}public String getApproverValue(){return approverValue;}public void setApproverValue(String v){approverValue=v;}}
